import fs from 'node:fs';import{pathToFileURL}from'node:url';const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}return v;}
const valid={transactionId:'fixture',resolution:'manually-restored',confirmation:'finalize-recovery-record',evidence:{provenance:'observed',scope:'the exact Set'}};
const rows=[];async function run(args=valid,options={}){const sim=new DeterministicLiveSimulator(),calls=[],status={...sim.status(),operations:options.realtime!==undefined?['snapshot','realtime.stats']:['snapshot'],...(options.status??{})};if(options.transport)Object.assign(sim.state.playback.transport,options.transport);if(options.playingTargets)sim.state.playback.playingTargets=options.playingTargets;if(options.firedTargets)sim.state.playback.firedTargets=options.firedTargets;const adapter={status:()=>status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>sim.invoke(i),subscribe:l=>sim.subscribe(l),snapshotAsync:(c,r)=>sim.snapshotAsync(c,r),discoverAsync:(r,c)=>sim.discoverAsync(r,c),getAsync:(r,c)=>sim.getAsync(r,c),invokeAsync:async(i,c)=>{calls.push({invocation:i,deadline:c?.deadlineMs!==undefined});if(options.invokeFail)throw Error('injected status failure');if(i.operation==='realtime.stats')return options.realtime;if(i.operation==='audio.capture.status')return Object.hasOwn(options,'capture')?options.capture:{};return sim.invokeAsync(i,c);},refreshStatusAsync:async()=>{calls.push({refresh:true});if(options.refreshFail)throw Error('injected refresh failure');return status;}};if(!options.noRetire)adapter.retireTransactionAsync=async(id,c,terminal)=>{calls.push({retire:id,deadline:c?.deadlineMs!==undefined,terminal});if(options.retireFail)throw Error('injected retirement failure');};const host=new McpHost(adapter);const owner=options.owner??'transactions',record={id:'fixture',state:'applied',epoch:1,expiresAt:Date.now()+100000,...options.record};if(options.present!==false)host[owner].set('fixture',record);if(options.barrier)host.recoveryFinalizationInFlight=true;if(options.active)host.activeAsyncOperations=1;let result;try{result=clean(await host.liveRecoveryFinalizeAsync(1,args));}catch(e){result={error:e.message};}rows.push({args,options,result,calls,exists:host[owner].has('fixture'),barrier:host.recoveryFinalizationInFlight});}
for(const args of [null,[],{},0,false,'x',valid,{...valid,extra:true}])await run(args);for(const key of Object.keys(valid)){const p={...valid};delete p[key];await run(p);for(const value of[null,[],{},false,0,1,'','x','accepted-current-state',['manually-restored'],{toString:null}])await run({...valid,[key]:value});}for(const key of['provenance','scope','observedAt'])for(const value of[null,[],{},false,0,'','text','a'.repeat(513)])await run({...valid,evidence:{...valid.evidence,[key]:value}});
for(const owner of['transactions','arrangementTransactions','sessionStructureTransactions','deviceParameterTransactions','deviceParametersTransactions','auditionTransactions','transportTransactions','clipLaunchTransactions','noteEditTransactions','clipLifecycleTransactions','audioCaptureTransactions'])for(const state of['previewed','applying','applied','undoing','undone','uncertain','capturing','analyzing','stopping'])await run(valid,{owner,record:{state}});
for(const options of[{present:false},{barrier:true},{active:true},{noRetire:true},{retireFail:true},{refreshFail:true},{status:{connected:false}},{status:{epoch:2},record:{kind:'realtime-arm'}},{record:{kind:'realtime-arm'}},{record:{kind:'realtime-arm',state:'undone'}},{realtime:{armed:false,pending:0}},{realtime:{armed:true,pending:0}},{realtime:{armed:false,pending:1}},{realtime:{armed:false,pending:'0'}},{realtime:{}},{realtime:null},{realtime:{armed:false,pending:0},invokeFail:true}])await run(valid,options);
for(const key of['playing','arrangementRecord','sessionRecord'])for(const value of[true,false,null])await run(valid,{transport:{[key]:value}});for(const key of['playingTargets','firedTargets'])await run(valid,{[key]:[{trackRef:'track:one',clipSlotRef:'slot:one',sceneRef:'scene:one',sceneIndex:0,clipRef:'clip:one'}]});
const capture={captureId:'capture:fixture',sourceSlotRef:'clip-slot:source',destinationSlotRef:'clip-slot:dest',state:'cleaned',active:false,playbackStopped:true};const record={state:'uncertain',captureId:capture.captureId,sourceSlotRef:capture.sourceSlotRef,destinationSlotRef:capture.destinationSlotRef};for(const value of[capture,{...capture,clip:{}},{...capture,clip:null},{...capture,residual:[]},{...capture,residual:['one']},...Object.keys(capture).map(key=>({...capture,[key]:null})),null])await run(valid,{owner:'audioCaptureTransactions',record,capture:value});
fs.writeFileSync(new URL('host-recovery-oracle.json',import.meta.url),JSON.stringify({rows}));console.log({rows:rows.length});
